const API_BASE=window.API_BASE||"/api",NATIVE=!!window.HIVEX_NATIVE,NATIVE_TOKEN_KEY="hivex_native_token";function _getNativeToken(){if(!NATIVE)return null;try{return localStorage.getItem(NATIVE_TOKEN_KEY)}catch{return null}}function _setNativeToken(t){if(NATIVE)try{t&&localStorage.setItem(NATIVE_TOKEN_KEY,t)}catch{}}function _clearNativeToken(){try{localStorage.removeItem(NATIVE_TOKEN_KEY)}catch{}}async function apiFetch(path,options={}){const headers={"Content-Type":"application/json",...options.headers||{}};if(NATIVE){headers["X-Hivex-Native"]="1";const tok=_getNativeToken();tok&&(headers.Authorization="Bearer "+tok)}let res;try{res=await fetch(API_BASE+path,{credentials:"include",...options,headers,body:options.body?JSON.stringify(options.body):void 0})}catch(netErr){const e=new Error("Sem liga\xE7\xE3o ao servidor");throw e.status=0,e.cause=netErr,e}const raw=await res.text();let data={};try{data=raw?JSON.parse(raw):{}}catch{}if(!res.ok){NATIVE&&res.status===401&&_clearNativeToken();const msg=data.error||`Erro do servidor (${res.status})`,err=new Error(msg);throw err.status=res.status,err.body=raw.slice(0,200),err}return NATIVE&&data&&data.token&&_setNativeToken(data.token),data}const api={getCompanies(params){const qs=params?"?"+new URLSearchParams(params).toString():"";return apiFetch("/companies"+qs)},getCompany(id){return apiFetch("/companies/"+id)},createCompany(company){return apiFetch("/companies",{method:"POST",body:company})},updateCompany(id,data){return apiFetch("/companies/"+id,{method:"PUT",body:data})},deleteCompany(id){return apiFetch("/companies/"+id,{method:"DELETE"})},getCompanyStatus(email){return apiFetch("/companies/status?email="+encodeURIComponent(email))},getReviews(companyId){return apiFetch("/companies/"+companyId+"/reviews")},submitReview(companyId,score,comment){return apiFetch("/companies/"+companyId+"/reviews",{method:"POST",body:{score,comment}})},replyToReview(companyId,reviewId,reply){return apiFetch("/companies/"+companyId+"/reviews/"+reviewId+"/reply",{method:"POST",body:{reply}})},contactCompany(companyId,message){return apiFetch("/companies/"+companyId+"/contact",{method:"POST",body:{message}})},reportCompany(companyId,reason,details){return apiFetch("/companies/"+companyId+"/report",{method:"POST",body:{reason,details}})},trackEvent(companyId,type){apiFetch("/companies/"+companyId+"/event",{method:"POST",body:{type}}).catch(()=>{})},getAnalytics(companyId){return apiFetch("/companies/"+companyId+"/analytics")},adminStats(){return apiFetch("/admin/stats")},adminCompanies(params){const qs=params?"?"+new URLSearchParams(params).toString():"";return apiFetch("/admin/companies"+qs)},adminSetStatus(id,status){return apiFetch("/admin/companies/"+id+"/status",{method:"PUT",body:{status}})},adminSetFeatured(id,featured){return apiFetch("/admin/companies/"+id+"/featured",{method:"PUT",body:{featured}})},adminSetVerified(id,verified){return apiFetch("/admin/companies/"+id+"/verified",{method:"PUT",body:{verified}})},adminDeleteReview(id){return apiFetch("/admin/reviews/"+id,{method:"DELETE"})},adminReports(params){const qs=params?"?"+new URLSearchParams(params).toString():"";return apiFetch("/admin/reports"+qs)},adminSetReportStatus(id,status){return apiFetch("/admin/reports/"+id+"/status",{method:"PUT",body:{status}})},login(email,password){return apiFetch("/auth/login",{method:"POST",body:{email,password}})},register(data){return apiFetch("/auth/register",{method:"POST",body:data})},logout(){return apiFetch("/auth/logout",{method:"POST"}).finally(_clearNativeToken)},getMe(){return apiFetch("/auth/me")},loginWithGoogle(idToken,type){return apiFetch("/auth/google",{method:"POST",body:{idToken,type}})},getAuthConfig(){return apiFetch("/auth/config")},requestPasswordReset(email){return apiFetch("/auth/forgot-password",{method:"POST",body:{email}})},resetPassword(token,password){return apiFetch("/auth/reset-password",{method:"POST",body:{token,password}})},changePassword(currentPassword,newPassword){return apiFetch("/auth/change-password",{method:"POST",body:{currentPassword,newPassword}})},deleteAccount(password){return apiFetch("/auth/me",{method:"DELETE",body:{password}}).finally(_clearNativeToken)},getFavourites(){return apiFetch("/favourites")},addFavourite(companyId){return apiFetch("/favourites/"+companyId,{method:"POST"})},removeFavourite(companyId){return apiFetch("/favourites/"+companyId,{method:"DELETE"})},bulkAddFavourites(ids){return apiFetch("/favourites/bulk",{method:"POST",body:{ids}})}};window.api=api;
